1	#!/usr/bin/env bun
2	/**
3	 * write_credentials_file.ts — collect this run's credentials into a JSON file for
4	 * `atoma run --credentials-file`.
5	 *
6	 * ## Why a file, and why this step exists at all
7	 *
8	 * A value in an environment block cannot be taken back. `/proc/<pid>/environ`
9	 * reflects what was placed on the stack at `execve`, and `unsetenv` does not
10	 * rewrite it — so anything that was ever in a process's environment stays
11	 * readable there, by any process of the same user, for that process's lifetime.
12	 *
13	 * The "Run agent" step's bash lives for the whole of `atoma run`. Giving it the
14	 * credentials therefore leaves them readable from `/proc` for minutes, to every
15	 * tool server the agent starts. Writing them here instead means only THIS step's
16	 * bash ever holds them, and it exits before the agent begins.
17	 *
18	 * atoma reads the file and deletes it before starting any tool server, so the
19	 * file and the servers never coexist. From then on the values are in atoma's
20	 * heap, which is out of reach: it makes itself non-dumpable.
21	 *
22	 * ## What goes in
23	 *
24	 * The credentials atoma itself needs (the provider key), the GitHub token the
25	 * `github`/`search`/`atoma` servers authenticate with, and whatever this project
26	 * declared in `tools.secrets`. Nothing else — this is not a dump of the
27	 * environment.
28	 *
29	 * Empty values are omitted rather than written as `""`. An unset repository
30	 * secret arrives as an empty string, and a present-but-empty key would tell
31	 * atoma's provider detection that a provider is configured when it is not.
32	 *
33	 * ## Where
34	 *
35	 * `$RUNNER_TEMP`, which is outside the workspace, so the checkout cannot have
36	 * placed a file there and nothing commits it by accident. tmpfs (`/dev/shm`)
37	 * would additionally keep the value off persistent storage, which is what
38	 * Kubernetes does for the same reason; that is worth measuring on a runner before
39	 * relying on it.
40	 *
41	 * Usage:
42	 *   write_credentials_file.ts --out "$RUNNER_TEMP/atomaton-credentials.json"
43	 */
44	import { writeFileSync } from "node:fs";
45	import { parseArgs } from "node:util";
46	import { RUN_CREDENTIALS, SECRET_NAMES_VAR, SECRET_SLOT_PREFIX, SECRET_SLOTS } from "../../domain/delivery/declared-secrets.ts";
47	import { defineScript } from "./lib/script-ref.ts";
48	
49	export interface WriteCredentialsFileArgs {
50	  /** Path to write. Must be outside the workspace. */
51	  out: string;
52	}
53	
54	export const ref = defineScript<WriteCredentialsFileArgs>(import.meta.url);
55	
56	/** The credentials to write, from the environment this step was given. */
57	export function collect(env: Record<string, string | undefined>): Record<string, string> {
58	  const out: Record<string, string> = {};
59	
60	  // `RUN_CREDENTIALS` rather than a list of this script's own. The names the run
61	  // supplies and the names a project may not declare are the same names, and
62	  // keeping two copies had already let one drift: `ATOMA_COPILOT_TOKEN` was here
63	  // and not in `TOOL_SECRETS.reserved`, so `tools.secrets` could name it and the
64	  // loop below would overwrite the run's own provider credential with it.
65	  for (const name of RUN_CREDENTIALS) {
66	    const value = env[name];
67	    if (value) out[name] = value;
68	  }
69	
70	  // Declared tool credentials arrive in numbered slots, because a step's `env:`
71	  // is a static map and cannot be keyed by a name the workflow does not know.
72	  let declared: string[] = [];
73	  try {
74	    declared = JSON.parse(env[SECRET_NAMES_VAR] || "[]") as string[];
75	  } catch {
76	    console.error(`::warning::${SECRET_NAMES_VAR} was not valid JSON; no declared credentials will be written.`);
77	  }
78	
79	  declared.slice(0, SECRET_SLOTS).forEach((name, slot) => {
80	    const value = env[`${SECRET_SLOT_PREFIX}${slot}`];
81	    if (value) out[name] = value;
82	    else {
83	      console.error(
84	        `::warning::config.yaml declares ${name}, but this repository has no secret by that name. Whatever needs it will fail.`,
85	      );
86	    }
87	  });
88	
89	  return out;
90	}
91	
92	function main(): void {
93	  const { values } = parseArgs({ args: Bun.argv.slice(2), options: { out: { type: "string" } } });
94	  if (!values.out) {
95	    console.error("usage: write_credentials_file.ts --out FILE");
96	    process.exit(2);
97	  }
98	
99	  const credentials = collect(process.env);
100	  // Mode 0600, and it is not only a gesture. Every tool server runs as
101	  // ONE dedicated user and this file is chowned to it, so 0600 is what keeps the
102	  // file from the user this step runs as once it has been handed over.
103	  //
104	  // What actually protects it is that atoma deletes it before starting any server.
105	  // That delete needs write permission on the containing DIRECTORY, which is why
106	  // the runner creates that directory owned by the tool user — see
107	  // `CREDENTIALS_DIR` in atomaton-runner.wac.ts. Put this file somewhere the tool user
108	  // cannot unlink from and every credential in it stays readable for the whole run,
109	  // because the core's delete is best-effort and only warns.
110	  writeFileSync(values.out, JSON.stringify(credentials), { mode: 0o600 });
111	
112	  // Names only, never values. Which credentials a run carries is already public
113	  // in config.yaml, and saying so is what makes a missing one diagnosable.
114	  console.error(
115	    `Wrote ${Object.keys(credentials).length} credential(s) for this run: ${Object.keys(credentials).join(", ")}`,
116	  );
117	}
