1	#!/usr/bin/env bun
2	/**
3	 * write_tools_file.ts — writes the tools file `atoma --tools-file` reads, from
4	 * `tools.servers` in config.yaml, immediately before it is needed.
5	 *
6	 * ## Why this exists
7	 *
8	 * The tools file used to be built once, in this template's `synth`, and shipped
9	 * inside the release. An adopter therefore received two files that agreed only
10	 * because they were built together here, and then drifted — because nothing in an
11	 * adopted repository ever regenerated one from the other.
12	 *
13	 * The consequences were asymmetric and both silent. Remove a server from
14	 * `tools.servers` and nothing happens: the shipped tools file still has it, and the
15	 * agent still gets it. Add one and the run is blocked: `atoma validate` resolves
16	 * `mcp_servers` against the tools file, which does not have it. Meanwhile the
17	 * documentation and the review skill both told people that `tools.servers` was where
18	 * tool servers are configured.
19	 *
20	 * A generated file that is distributed is a second source of truth wearing the
21	 * clothes of a first. So it is not distributed any more. It is written here, per
22	 * run, and thrown away with the runner.
23	 *
24	 * ## Which config it reads, and why that is the whole security question
25	 *
26	 * A tools file names `command` for every server, so whoever writes it chooses what
27	 * processes the run starts. Generating from a pull request's own `config.yaml` would
28	 * let any pull request run anything — the "a pull request may not decide its own
29	 * execution environment" rule, crossed at its widest point.
30	 *
31	 * `--config` is therefore given the machinery checkout's config, which
32	 * `atomaton-runner.yml` takes from the default branch. This script does no fetching and
33	 * makes no decision about trust: it writes what it is pointed at, and the caller is
34	 * responsible for pointing it at something a person merged.
35	 *
36	 * ## Usage
37	 *
38	 *   write_tools_file.ts --config <config.yaml> --out <tools.yaml> --hook-base <dir>
39	 *
40	 * `--hook-base` is the directory relative hook paths are written against — the
41	 * `tools/` directory of the tree the hook scripts live in. See `domain/machinery/tools-file.ts`
42	 * for why the output carries absolute paths.
43	 */
44	import { mkdirSync, readFileSync, writeFileSync } from "node:fs";
45	import { dirname } from "node:path";
46	import { parseArgs } from "node:util";
47	import { reservedServerNames, toolsFileFrom, type ToolsSection } from "../../domain/machinery/tools-file.ts";
48	import { defineScript } from "./lib/script-ref.ts";
49	
50	export interface WriteToolsFileArgs {
51	  config: string;
52	  out: string;
53	  "hook-base": string;
54	  /** The shipped `tools/defaults.yaml`. Passed rather than derived -- see
55	   * `domain/machinery/shipped-servers.ts` for the layout the derivation got wrong. */
56	  defaults: string;
57	}
58	
59	export const ref = defineScript<WriteToolsFileArgs>(import.meta.url);
60	
61	function main(): void {
62	  const { values } = parseArgs({
63	    args: Bun.argv.slice(2),
64	    options: {
65	      config: { type: "string" },
66	      out: { type: "string" },
67	      "hook-base": { type: "string" },
68	      defaults: { type: "string" },
69	    },
70	  });
71	
72	  if (!values.config || !values.out || !values["hook-base"] || !values.defaults) {
73	    console.error(
74	      "usage: write_tools_file.ts --config config.yaml --defaults defaults.yaml --out tools.yaml --hook-base DIR",
75	    );
76	    process.exit(2);
77	  }
78	
79	  let tools: ToolsSection | undefined;
80	  try {
81	    const config = Bun.YAML.parse(readFileSync(values.config, "utf8")) as { tools?: ToolsSection };
82	    tools = config.tools;
83	  } catch (error) {
84	    // Fail loudly. Every server an agent uses is in this file, so a run started
85	    // without it is a run with no tools -- which looks like a confused agent rather
86	    // than a broken configuration, and costs somebody an afternoon to tell apart.
87	    console.error(`::error::${values.config}: could not read the tool servers: ${(error as Error).message}`);
88	    process.exit(1);
89	  }
90	
91	  const collisions = reservedServerNames(tools);
92	  if (collisions.length > 0) {
93	    console.error(
94	      `::error::${values.config}: \`tools.servers\` may not be named ${collisions.join(", ")} — ` +
95	        "`hooks` is the core's reserved key for the hooks that apply to every server, so a server " +
96	        "by that name would silently become one.",
97	    );
98	    process.exit(1);
99	  }
100	
101	  const file = toolsFileFrom(tools, values["hook-base"], values.defaults);
102	  mkdirSync(dirname(values.out), { recursive: true });
103	  writeFileSync(
104	    values.out,
105	    `# Generated from ${values.config} for this run. Not a file to edit or keep.\n` +
106	      // Indented rather than flow style: this is read by a person exactly once, when
107	      // something about a server is being diagnosed, and one long line helps nobody.
108	      Bun.YAML.stringify(file, null, 2).replace(/[ \t]+$/gm, ""),
109	  );
110	  console.error(`write_tools_file: ${Object.keys(file).length} entries -> ${values.out}`);
111	}
112	
113	if (import.meta.main) main();

