308	/**
309	 * Validate one destination's declaration and put it in slot order.
310	 *
311	 * Absent and `[]` both mean "no credentials here", which is the normal case and
312	 * not a problem. Anything else that cannot be honoured exactly is a problem:
313	 * this returns names only when every one of them is usable, because a partially
314	 * applied credential list gives the process a confusing runtime failure instead
315	 * of a configuration error anyone can act on.
316	 */
317	export function resolveDeclaredSecrets(raw: unknown, destination: SecretDestination): SecretsResolution {
318	  const { field, reserved } = destination;
319	  if (raw === undefined || raw === null) return { names: [], problems: [] };
320	
321	  if (!Array.isArray(raw)) {
322	    return { names: [], problems: [`\`${field}\` must be an array of secret names.`] };
323	  }
324	
325	  const problems: string[] = [];
326	  const names: string[] = [];
327	  const seen = new Set<string>();
328	
329	  for (const entry of raw) {
330	    if (typeof entry !== "string") {
331	      problems.push(`\`${field}\` entries must be strings; found ${JSON.stringify(entry)}.`);
332	      continue;
333	    }
334	    const name = entry.trim();
335	    if (!NAME_PATTERN.test(name)) {
336	      problems.push(
337	        `\`${field}\`: '${name}' is not a usable secret name. Expected uppercase letters, digits and underscores, starting with a letter — e.g. 'SLACK_TOKEN'.`,
338	      );
339	      continue;
340	    }
341	    if (reserved.has(name)) {
342	      problems.push(
343	        `\`${field}\`: '${name}' is already part of the environment this workflow provides, so declaring it would replace that value rather than add a credential. Give the secret another name.`,
344	      );
345	      continue;
